package edu.facilities.ui; import edu.facilities.service.*; import javafx.fxml.*; import javafx.scene.control.*; import java.sql.*;
public class MaintenanceController { @FXML private TextField roomIdField; @FXML private TextArea descriptionField; @FXML private Label messageLabel; @FXML private void submit(){try{var u=AuthService.getInstance().getCurrentUser();if(u==null)throw new IllegalArgumentException("Please log in.");long id=new MaintenanceService().createTicket(roomIdField.getText(),descriptionField.getText(),u);messageLabel.setText("Ticket #"+id+" created with status PENDING.");}catch(Exception e){messageLabel.setText(e.getMessage());}}}
